def extostr(cls, e, max_level=30, max_path_level=5):
    """
    Format an exception.

    :param e: Any exception instance.
    :type e: Exception
    :param max_level: Maximum call stack level (default 30)
    :type max_level: int
    :param max_path_level: Maximum path level (default 5)
    :type max_path_level: int
    :return The exception readable string
    :rtype str
    """
    def exception_str(e, level):
        if level >= max_level:
            return 'Exception (max depth)'
        str_result = e.__class__.__name__
        if isinstance(e, Exception):
            str_result += ': ' + str(e)
        str_result += ' at '
        if level < max_path_level:
            if hasattr(e, 'path'):
                str_result += str(e.path)
            else:
                str_result += str(e)
            str_result += '\n'
        for frame in e.__traceback__.flatten():
            if frame.f_code.co_filename != exception_str.__code__.co_filename:
                extra_path_level = 2 if level < max_path_level else 3
                stringified_frame = extract_exception_trace(frame, extra_path_level)
                str_result += stringified_frame + ' in ' + frame.f_code.co_filename + ':' + str(frame.f_lineno) + '\n'
            level += 1
        return str_result

    return exception_str(e, 0)

