def validate_version_inventories(self, version_dirs):
    """Each version SHOULD have an inventory up to that point.

    Also keep a record of any content digests different from those in the root inventory
    so that we can also check them when validating the content.

    version_dirs is an array of version directory names and is assumed to be in
    version sequence (1, 2, 3...).
    """

    version_info = {}
    root_directory = self.root_directory  # Assuming self has a root_directory method

    try:
        for directory in version_dirs:
            inventory_path = os.path.join(directory, 'inventory.txt')

            # Check if this version has an inventory
            if not os.path.exists(inventory_path):
                raise FileNotFoundError(f"No inventory found for version {directory}")

            with open(inventory_path, 'r') as f:
                inventory_content = f.read()
                version_info[directory] = inventory_content

            # Check if the content digests are different from the root inventory
            root_digest = root_directory.get_content_digest(directory)
            if root_digest != inventory_digest:
                self.diff_digests[directory] = (root_digest, inventory_digest)

    except FileNotFoundError as e:
        print(f"Error: {e}")
    except Exception as e:
        print(f"An unexpected error occurred: {e}")

