def parse_subparser_arguments(unparsed_arguments, subparsers):
    result = {}
    remaining_args = []

    for subparser_name, parser in subparsers.items():
        try:
            parsed_args = parser.parse_args(unparsed_arguments)
            result[subparser_name] = parsed_args
        except SystemExit:
            remaining_args = parsed_arguments[1:]

    return result, remaining_args

