    if not isinstance(alphabet, list) or not all(isinstance(s, str) for s in alphabet):
        raise ValueError("Alphabet must be a list of strings")
    if padding is not None and not isinstance(padding, int):
        raise ValueError("Padding must be an integer")

    num_str = ""
    remainder = number

    while remainder > 0:
        remainder, digit = divmod(remainder, len(alphabet))
        num_str = alphabet[digit] + num_str

    if padding is not None:
        num_str = num_str.rjust(padding, alphabet[0])

    return num_str

