def _parse_image_ref(image_href: str) -> Tuple[str, str, bool]:
    """Parse an image href into composite parts.

    :param image_href: href of an image
    :returns: a tuple of the form (image_id, netloc, use_ssl)
    :raises ValueError:

    """
    try:
        parsed_url = urlparse(image_href)

        if parsed_url.scheme:
            use_ssl = True
        else:
            use_ssl = False

        # Extract the image_id
        if 'id=' in parsed_url.parser['query']:
            image_id = parsed_url.parser['query'].split('id=')[1]
        else:
            image_id = None

        return image_id, parsed_url.netloc, use_ssl
    except ValueError as e:
        raise ValueError(f"Unable to parse image href {image_href}. Error: {e}")

