def run_command(commands: List[str], args: Optional[List[str]] = None, cwd: str = None, verbose: bool = False, hide_stderr: bool = False, env: dict = None) -> str:
    """Call the given command(s)."""


    full_args = commands + (args or [])

    with Popen(full_args, stdin=PIPE, stdout=PIPE, stderr=PIPE if not hide_stderr else None, cwd=cwd, env=env) as process:
        stdout, stderr = process.communicate()

        final_output = stdout.decode('utf-8').strip()
        if stderr:
            if verbose:
                print("stderr:", stderr.decode('utf-8'))
            raise subprocess.CalledProcessError(process.returncode, "Command output:", final_output)

        if verbose:
            print("Command output:", final_output)

    return final_output

def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    try:
        if verbose:
            print(f"Running command: {commands} {args}")
        result = subprocess.run([commands] + args, cwd=cwd, text=True, stdout=subprocess.PIPE, stderr=subprocess.PIPE, env=env, check=True)
