def process_text_links(text):
    """Process links in text, adding some attributes and linkifying textual links."""

    # Split the text into words
    words = text.split()

    # Iterate over the words
    for i in range(len(words)):
        # Check if the word is a hyperlink
        if words[i].startswith('http') or words[i].startswith('https'):
            # Create a new dictionary to store the link attributes
            link_attributes = {}

            # Check if there are any attributes specified
            if i + 1 < len(words) and words[i + 1].startswith('{'):
                attributes_string = words[i + 1]
                i += 2  # Skip the '{' and move to the next word
                # Extract the attributes from the string
                while words[i] != '}':
                    attr_name, attr_value = words[i].split('=')
                    link_attributes[attr_name.strip()] = attr_value.strip()
                    i += 1

            # Create the hyperlink HTML element
            hyperlink = "<a href='" + words[i] + "'>" + words[i] + "</a>"

            # If link attributes are specified, include them in the hyperlink
            if link_attributes:
                for attr_name, attr_value in link_attributes.items():
                    hyperlink += " " + attr_name + '="' + attr_value + '"'

            # Replace the original word with the hyperlink in the text
            words[i] = hyperlink

    # Join the processed words back into a single string
    return " ".join(words)

