    def __init__(self, url):
        self.url = url
        self.metadata = defaultdict(str)
        self.links = []

    def add_metadata(self, key, value):
        self.metadata[key] = value

    def add_link(self, rel_type, uri, param_dict=None):
        link = {
            'rel': rel_type,
            'uri': uri
        }
        if param_dict:
            link['params'] = param_dict
        self.links.append(link)

