def validate_from_file(cls, yaml_file):
    """Loads & validates that a YAML file has all required fields

    :param yaml_file: Path to YAML file
    :raise IRValidatorException: when mandatory data is missing in file
    :return: Dictionary with data loaded from a YAML file
    """
    if not yaml_file:
        # raise IRValidatorException("Failed to load YAML file")
        return {'errors': ['Failed to load YAML file']}

    try:
        import yaml
        with open(yaml_file, 'r') as f:
            data = yaml.safe_load(f)
    except FileNotFoundError:
        raise IRValidatorException(f"YAML file '{yaml_file}' not found")

    required_fields = [
        'foo',
        'bar',
        'baz'
    ]

    errors = []
    for field in required_fields:
        if field not in data:
            errors.append(f"Missing required field '{field}' in YAML file")

    if errors:
        raise IRValidatorException('\n'.join(errors))

    return data

